using System.Drawing;
using System.Windows.Forms;
using System.Windows.Forms.Design;
public class MyControl : UserControl
{
    private readonly StatusStrip _statusStrip;

    public MyControl()
    {
        _statusStrip = new StatusStrip();
        // .NET 9 changed the default RenderMode from ManagerRenderMode
        // (Professional) to System. Restore the .NET 8 appearance.
        _statusStrip.RenderMode = ToolStripRenderMode.Professional;
        Controls.Add(_statusStrip);
    }

    public string DisplayName { get; set; }
    public int MaxItems { get; set; }

    /// <summary>
    /// Shows a drop-down editor, guarding against null controls which now
    /// throw ArgumentNullException in .NET 9.
    /// </summary>
    public static void ShowDropDown(IWindowsFormsEditorService editorService, Control control)
    {
        if (control is null)
            return;

        editorService.DropDownControl(control);
    }
}

